n("אגם", "אגם הוא גוף של מים עומדים שמוקף יבשה. בעברית המקראית המילה מתארת גם ביצה ובריכה, ובתהילים היא מופיעה בתמונה של מדבר שהופך לאגם מים. בעברית של היום אגם הוא שם שניתן לבנות ולבנים, ומעלה תמונה של מים שקטים.")
n("ישי", "בתנ״ך ישי הוא בנו של עובד ונכדם של בועז ורות, איש בית לחם ואביו של דוד המלך. מקור השם אינו ודאי, ויש שפירשו אותו מלשון יש, כלומר קיים, או כצורה קצרה של שם שכולל את שם האל. בספר דברי הימים הוא נקרא גם אישי.")
n("נגה", "נוגה הוא אור בהיר וזוהר, ובעברית המקראית המילה מתארת את אור השחר ואת זוהר האש. נוגה הוא גם השם העברי של כוכב הלכת ונוס, שנראה בשמיים לפני הזריחה ואחרי השקיעה. השם נכתב גם בכתיב חסר, נגה, כמו במקרא.")
n("ריף", "באנגלית ריף הוא שונית, רצועה של סלעים או אלמוגים מתחת לפני הים, ובמוזיקה ריף הוא גם משפט מוזיקלי שחוזר. בערבית ריף הוא אזור כפרי פורה, ומכאן גם שמו של אזור הריף בצפון מרוקו. השם ניתן לבנים ולבנות.")
n("יהודית", "יהודית היא אישה מבני יהודה, והשם בנוי על אותו שורש כמו יהודה, מלשון הודיה ותודה. זה גם שמה של גיבורת ספר יהודית, אחד הספרים החיצוניים, שנכתבו בימי הבית השני ולא נכללו בכתבי הקודש. יהודה הוא הצורה שניתנת לבנים.", ["יהודה"])
n("הדסה", "הדסה בנויה על שם השיח הדס, שיח ריחני שענפיו הם אחד מארבעת המינים בחג הסוכות. במגילת אסתר הדסה הוא שמה העברי של אסתר, שגדלה בבית מרדכי בשושן. מאותה מילה בא גם השם הדס.", ["הדס"])
n("בניה", "השם מחבר את הפועל בנה עם שם האל, ופירושו ה׳ בנה. בתנ״ך בניה בן יהוידע הוא מגיבורי דוד, ובימי שלמה עמד בראש הצבא. השם מופיע במקרא גם בצורה הארוכה בניהו, ובעברית אפשר לשמוע בו גם בן־יה.", ["בניהו"])
n("עידו", "בתנ״ך עדו הוא אביו של ברכיה וסבו של הנביא זכריה, ובדברי הימים מוזכר גם עדו החוזה, נביא מימי רחבעם. מקור השם אינו ודאי, ויש שקשרו אותו למילה עדי, תכשיט. בעברית של היום הוא נכתב בדרך כלל עם יוד, עידו.")
n("אלמה", "בשפות כמו איטלקית, ספרדית ופורטוגזית אלמה היא נשמה, מילה שהגיעה לשפות האלה מהלטינית. בעברית השם נשמע כמו עלמה, נערה צעירה, אבל נכתב באלף ובא משפה אחרת. כך מתחבר בשם צליל מוכר בעברית עם מילה מהשפות הרומאניות.")
n("תהילה", "תהילה היא שבח, מהשורש ה־ל־ל, שממנו באים גם הלל והללויה. ספר תהילים נקרא על שם המילה הזאת, כי רבים ממזמוריו הם שירי שבח. מאותה מילה נבנו גם השמות תהל ותהלה, ותהלה היא גם כתיב חסר של תהילה.", ["תהלה", "תהל"])
n("שילה", "שילה היא עיר בהר אפרים, שבה עמד המשכן בימי השופטים, ושם גדל שמואל הנער בבית עלי הכהן. בברכת יעקב מופיעה המילה שילה במשפט סתום, שהפרשנים הסבירו בדרכים שונות. השם נכתב גם שילו, כמו שם העיר בכמה מקומות במקרא.", ["שילו"])
n("מעיין", "מעיין הוא מקום שבו מים יוצאים מהאדמה מעצמם, והמילה בנויה על עין, כמו עין המים. בתנ״ך המעיין מופיע כתמונה של שפע ושל ישועה, ובארץ נקראו מקומות רבים על שם מעיינות. השם ניתן לבנות ולבנים.")
n("הראל", "בספר יחזקאל הראל הוא החלק העליון של המזבח, ומכאן הקשר של השם לבית המקדש. את המילה נוהגים לפרש כצירוף של הר ואל, הר האלוהים. השם בנוי כמו שמות עבריים אחרים שמחברים מילה עם אל, כמו אריאל ונתנאל.")
n("עילאי", "עילאי היא מילה ארמית שפירושה עליון ונעלה, מאותו שורש של המילים העבריות עלייה ועליון. מאותו שורש באה גם המילה הארמית לעילא, שמוכרת מהתפילה. בשם יש גם את הסיומת ־אי, שמוכרת משמות רבים מימי המשנה והתלמוד.")
n("עמית", "עמית בעברית המקראית הוא חבר ושכן, אדם שחי לצדך באותה קהילה. המילה מופיעה בתורה בעיקר בחוקים שמסדירים יחסים בין אדם לחברו, כמו האיסור לשקר לעמית. בעברית של היום עמית הוא גם חבר לעבודה, ושם שניתן לבנים ולבנות.")
n("אמיר", "בעברית המקראית אמיר הוא הענף העליון של העץ, צמרתו, ובספר ישעיהו המילה מופיעה בתמונה של פירות שנשארו בראש העץ. בערבית אמיר הוא מושל ומפקד, מהשורש א־מ־ר, ומכאן התואר אמיר. אמירה היא הצורה שניתנת לבנות.", ["אמירה"])
n("ליב", "בשפות סקנדינביה ליב היא חיים, ובנורווגית ובשוודית זה גם שם לבנות. ביידיש לייב הוא אריה, וזה שם פרטי ותיק לבנים בקהילות אשכנז, לפעמים בצירוף כמו אריה לייב. בעברית אפשר לשמוע בשם גם את המילה לב.")
n("אלישבע", "השם מחבר את המילה אלי עם שבע, מלשון שבועה, ופירושו אלוהיי הוא שבועה. בתורה אלישבע בת עמינדב היא אשתו של אהרן הכהן ואחותו של נחשון. מהשם הזה נבנה, דרך היוונית, השם אליזבת, שמוכר בשפות רבות.")
n("רום", "רום הוא גובה, מקום גבוה, ובעברית המקראית המילה מתארת גם את השמיים ואת המרומים. מאותו שורש באות המילים רוממות והרמה, וגם השמות רם ורומי. השם ניתן לבנים ולבנות.", ["רומי"])
n("לין", "לין היא מילה ערבית מהשורש ל־י־ן, שעניינו רכות, גמישות ועדינות. מאותו שורש בא גם השם ליאן, שמשמעו קרוב מאוד. בעברית השם קצר וקל לכתיבה, ונשמע קרוב למילה לינה, אבל אין ביניהן קשר.", ["ליאן"])
n("אבישג", "בתנ״ך אבישג השונמית היא נערה מהעיר שונם, שהובאה לבית המלך לשרת את דוד בזקנתו. אחרי מותו של דוד ביקש אדוניה לשאת אותה לאישה, והבקשה הובילה לסכסוך עם שלמה. מקור השם אינו ידוע, אבל חלקו הראשון, אבי, מוכר משמות עבריים רבים.")
n("שקד", "שקד הוא עץ שפורח בסוף החורף, לפני רוב העצים, ומכאן קשרו את שמו לפועל שקד, להיות ער וזהיר. בספר ירמיהו מופיע משחק המילים הזה במראה של מקל שקד. פריחת השקד הלבנה והוורודה קשורה בארץ לט״ו בשבט.")
n("עדי", "עדי הוא תכשיט, כל מה שעונדים לנוי, ובעברית המקראית המילה מופיעה כמעט תמיד במובן הזה. מאותה מילה נבנו השמות עדיה ועדיאל, שמוסיפים לה את שם האל. השם ניתן לבנות ולבנים.", ["עדיה", "עדיאל"])
n("נתנאל", "השם מחבר את הפועל נתן עם שם האל, ופירושו אלוהים נתן. בתורה נתנאל בן צוער הוא הנשיא של שבט יששכר במדבר. מאותו פועל נבנו גם השמות נתן, יהונתן ויונתן, שכולם מתארים מתנה מאלוהים.", ["נתן", "יהונתן", "יונתן"])
n("אפרת", "אפרת היא שם קדום של בית לחם ושל האזור שסביבה, ובתורה רחל נקברה בדרך אפרתה. אפרת היא גם אשתו של כלב בן חצרון. את השם נוהגים לקשר לשורש פ־ר־ה, של פרי ופוריות, אבל המקור אינו ודאי.")
n("נבו", "נבו הוא הר בעבר הירדן המזרחי, בארץ מואב, שממנו ראה משה את הארץ לפני מותו. השם קשור כנראה לנבו, אל החוכמה והכתיבה הבבלי, שעל שמו נקראו גם מקומות ואנשים בעולם העתיק.")
n("נוה", "נווה הוא מקום מגורים, בעיקר מרעה שבו שוכנים הרועים והצאן, ובשירה המקראית גם בית ומשכן. בספר ישעיהו ירושלים מתוארת כנווה בטוח ושקט. המילה מופיעה בשמות של יישובים ושכונות רבים, ובעברית המקראית יש לה גם משמעות של יופי.")
n("רני", "בעברית רני הוא ציווי מהשורש ר־נ־ן, קריאה לשמוח ולשיר. בערבית ראני, באלף, פירושו מי שמביט ומתבונן, ובכתיב עברי שני השמות נראים אותו דבר. מאותו שורש עברי באים גם רון, רן, רוני ורינה.", ["רוני", "רון", "רינה", "רן"])
n("טוהר", "טוהר הוא ניקיון, בגוף ובנפש, מהשורש ט־ה־ר. מאותו שורש באות המילים טהרה וטהור, שמשמשות בעברית במובן מוחשי וגם במובן מוסרי. השם ניתן לבנות ולבנים, ונכתב גם בכתיב חסר, טהר.", ["טהר"])
n("עבד", "עבד בעברית ובערבית הוא מי שעובד ומשרת, מהשורש ע־ב־ד, המשותף לשתי השפות. בערבית השם הוא לרוב חלק משם מורכב, כמו עבדאללה או עבד אלרחמן, שבו הוא מצורף לאחד מכינויי האל. בעברית מאותו שורש בא השם עובדיה.", ["עבדאללה"])
n("דבורה", "דבורה היא החרק שמייצר דבש, ושמה העברי עתיק. בתנ״ך דבורה היא נביאה ששפטה את ישראל, ועם ברק בן אבינועם הובילה את הניצחון על סיסרא. שירת דבורה נחשבת לאחד השירים העתיקים במקרא, וגם מינקת רבקה נקראה דבורה.")
n("ניב", "ניב הוא דיבור ומבע, ובספר ישעיהו המילה מתארת את מה שיוצא מהשפתיים. בעברית של היום ניב הוא גם צורת דיבור של שפה באזור מסוים, וגם ביטוי קבוע, כמו בצירוף ניבים ופתגמים. מאותה מילה נבנה גם השם ניבי.", ["ניבי"])
n("נתן", "השם בא מהפועל נתן, ופירושו הוא נתן, כלומר מתנה. בתנ״ך נתן הנביא הוא היועץ של דוד, שהוכיח אותו במשל כבשת הרש, וגם אחד מבניו של דוד נקרא נתן. מאותו פועל נבנו גם השמות נתנאל, יהונתן ויונתן.", ["נתנאל", "יהונתן", "יונתן"])
n("שי", "שי הוא מתנה, ובעברית המקראית המילה מתארת מנחה שמביאים למלך או לבית המקדש. בעברית של היום היא משמשת בעיקר בצירופים כמו שי לחג. השם ניתן לבנים ולבנות, וממנו נבנה גם השם שי־לי.", ["שי-לי"])
n("שי-לי", "השם מחבר שתי מילים עבריות, שי ולי, ופירושו מתנה שניתנה לי. הוא בנוי כמו שמות עבריים חדשים אחרים שמצרפים את המילה לי למילה אחרת, כמו ליאור. המילה שי מוכרת מהעברית המקראית במובן של מנחה ומתנה.", ["שי"])
n("הללי", "הללי הוא ציווי מהשורש ה־ל־ל, שפירושו שבחי, בפנייה בלשון נקבה, למשל אל הנפש. מאותו שורש באים הלל, הללויה ותהילה, והמילה מוכרת בעיקר ממזמורי תהילים. מאותה מילה נבנו גם השמות הלל והלליה.", ["הלל", "הלליה"])
n("אלון", "אלון הוא עץ גדול וחסון שגדל בחורש של ארץ ישראל, ופירותיו הם הבלוטים. בתנ״ך האלון מופיע כציון מקום, ותחת אלון ליד בית אל נקברה דבורה, מינקת רבקה. מאותה מילה נבנו גם השמות אלונה ואילון.", ["אלונה", "אילון"])
n("ינאי", "ינאי נוצר כצורה קצרה של יהונתן, בדרך שבה דוברי ארמית קיצרו שמות עבריים והוסיפו להם את הסיומת ־אי. באותה דרך נוצרו באותה תקופה שמות נוספים שמסתיימים באי. השם מוכר מימי הבית השני ומספרות חז״ל.", ["יהונתן", "יונתן"])
n("עדן", "עדן בעברית היא עונג ונעימות, ומאותו שורש באות המילים עדנה ועדין. בתורה עדן הוא המקום שבו נטע אלוהים את הגן, ולכן גן העדן הוא תמונה של מקום שליו ומושלם. השם ניתן לבנות ולבנים.")
n("כרם", "בעברית כרם הוא שטח של גפנים, ובמקרא הוא מופיע פעמים רבות כתמונה של שפע ושל עבודת האדמה, כמו בשירת הכרם של ישעיהו. בערבית כַּרַם פירושו נדיבות, מאותו שורש של כרים, נדיב. מאותה מילה עברית נבנה גם השם כרמי.", ["כרמי"])
n("ניתאי", "ניתאי הוא שם בצורה ארמית, עם הסיומת ־אי שמוכרת משמות רבים מתקופת המשנה והתלמוד. יש שמקשרים אותו לשורש נ־ת־ן, כצורה קצרה של שם כמו נתנאל, אבל המקור אינו ודאי. במשנה זה שמו של ניתאי הארבלי, אחד החכמים מימי הבית השני.")
n("אבראהים", "אבראהים הוא הצורה הערבית של אברהם, ובקוראן הוא נביא ואבי האמונה באל אחד. בתורה שמו של אברם שונה לאברהם, והשם פורש כאב המון גויים. גם היהדות וגם האסלאם רואות בו אב קדמון, ולכן השם משותף לשתי המסורות.", ["אברהם"])
n("נעמה", "נעמה בנויה על השורש נ־ע־ם, שעניינו נעימות ויופי, כמו נועם ונעים. בתורה נעמה היא אחותו של תובל קין, ובספר מלכים נעמה העמונית היא אמו של רחבעם המלך. בערבית נִעְמָה היא ברכה וחסד, מאותו שורש.", ["נועם", "נעמי"])
n("עוז", "עוז הוא כוח, חוזק וביטחון, ובעברית המקראית המילה מופיעה לעתים קרובות בתהילים ובשירה. מאותו שורש באים המילה עז והשמות עוזיאל ועוזיה. השם נכתב גם בכתיב חסר, עז.", ["עז", "עוזיאל"])
n("צבי", "צבי הוא חיה קלת רגליים שחיה בארץ ישראל, ובשיר השירים הדוד משול לצבי. בעברית המקראית צבי הוא גם יופי ותפארת, ומכאן הכינוי ארץ הצבי לארץ ישראל. צביה היא נקבת הצבי והצורה שניתנת לבנות.", ["צביה"])
n("הדר", "הדר הוא יופי, פאר וכבוד, ובעברית המקראית המילה מופיעה לרוב לצד הוד. מכאן גם פרי עץ הדר, האתרוג, שהוא אחד מארבעת המינים בחג הסוכות. בתורה הדר הוא גם שמו של אחד ממלכי אדום.")

